import {Monitor,POLICY} from './engine.mjs';
import {SCENARIOS,sample} from './scenarios.mjs';
import {sealReport} from './audit.mjs';
const $=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const meta={hr:{name:'Heart rate',unit:'bpm',color:'#178786',range:[55,160]},spo2:{name:'Oxygen saturation',unit:'%',color:'#4d83b6',range:[65,100]},rr:{name:'Respiratory rate',unit:'/min',color:'#8b79a6',range:[10,40]},activity:{name:'Activity',unit:'index',color:'#b18745',range:[0,1]}};
let monitor,scenario='exercise',t=0,running=false,timer=null,points=[],reviewId=null;
function stop(){running=false;clearInterval(timer);timer=null;}
function start(){if(t>=180)reset(scenario);running=true;clearInterval(timer);timer=setInterval(()=>advance(),1000/Number($('speed').value));renderControls();}
function reset(id){if(!SCENARIOS.some(s=>s.id===id))throw new Error('Unknown scenario');stop();scenario=id;monitor=new Monitor();points=[];t=0;reviewId=null;for(let i=0;i<=30;i++)advance(false);render();}
function advance(draw=true){if(t>=180){stop();renderControls();return;}const s=monitor.ingest(sample(scenario,t));points.push({t,...s.values,quality:s.quality,score:s.score});if(points.length>61)points.shift();t++;if(draw)render();}
function path(key,min,max,w=300,h=44){let d='',connected=false;for(const p of points){if(key!=='score'&&p.quality[key]<POLICY.qualityMin){connected=false;continue;}const x=points.length===1?0:(p.t-points[0].t)/60*w,y=h-4-Math.max(0,Math.min(1,(p[key]-min)/(max-min)))*(h-8);d+=`${connected?'L':'M'}${x.toFixed(1)},${y.toFixed(1)} `;connected=true;}return d;}
function renderControls(){$('play').textContent=running?'Ⅱ Pause':'▶ Run simulation';$('run-label').textContent=t>=180?'COMPLETE':running?'PLAYING':'PAUSED';$('clock').textContent=time(Math.max(0,t-1));$('step').disabled=running||t>=180;}
function render(){
  const explanationOpen=document.getElementById('explanation')?.open??false;
  renderControls();const s=monitor.latest;
  $('signals').innerHTML=Object.entries(meta).map(([k,m])=>{const good=s.valid.includes(k),v=s.values[k];return `<article class="signal-card"><div class="signal-head"><span>${m.name}</span><span class="quality-tag ${good?'':'bad'}">${good?'RELIABLE':'CHECK SENSOR'}</span></div><div class="value-row"><strong>${v===null||v===undefined?'—':v.toFixed(k==='spo2'?1:k==='activity'?2:0)}</strong><span>${m.unit}</span><small>${k==='activity'?(s.active?'Movement':'At rest'):'RAW SAMPLE'}</small></div><svg class="spark" viewBox="0 0 300 44" preserveAspectRatio="none" role="img" aria-label="${m.name}: last 60 simulated seconds; gaps mark rejected signals"><path d="M0 40H300" stroke="#edf2f4"/><path d="${path(k,...m.range)}" fill="none" stroke="${m.color}" stroke-width="2" stroke-linejoin="round"/></svg></article>`;}).join('');
  const d=path('score',0,100,720,125);$('risk-chart').innerHTML=`<g transform="translate(28 3)"><path d="M0 4H720 M0 62H720 M0 121H720" stroke="#e8eff2" fill="none"/><path d="M0 56.65H720" stroke="#c89b59" stroke-dasharray="5 5"/><text x="-25" y="8" fill="#80929d" font-size="10">100</text><text x="-19" y="66" fill="#80929d" font-size="10">50</text><text x="-12" y="124" fill="#80929d" font-size="10">0</text><path d="${d}" stroke="#0d8986" stroke-width="2.7" fill="none" stroke-linejoin="round"/><text x="0" y="142" fill="#80929d" font-size="10">${time(points[0].t)}</text><text x="685" y="142" fill="#80929d" font-size="10">${time(s.t)}</text></g>`;
  $('range').textContent=s.scoreRange[1]>s.score?'Missing-signal range: '+s.scoreRange.join('–'):'Full signal coverage';
  const copy=s.stale?'No fresh data. Physiological status is unknown.':s.issues.length?'Some observations are unreliable. Check signal capture; uncertainty does not establish safety.':!s.baseline?'Learning a resting baseline from 20 reliable samples.':s.episode?.status==='pending'?'A sustained pattern needs human interpretation. Review the evidence before confirming an observed concern.':s.episode?.status==='confirmed'?'Human-confirmed concern is marked high priority within this demo. No notification or medical action was sent.':s.score>=25?'A deviation is being observed. Escalation requires sufficient confidence, corroboration, and persistence.':s.active?'Higher heart rate and breathing align with activity. Context reduces their contribution.':'No sustained anomaly in the observed signals. Continue monitoring; this is not a health assessment.';
  $('assessment').innerHTML=`<span class="state-label ${['HIGH PRIORITY','REVIEW REQUESTED'].includes(s.state)?'urgent':['WATCH','SENSOR CHECK','NO DATA'].includes(s.state)?'warn':''}">${s.state}</span><div class="score-display"><strong>${s.stale?'—':s.score}</strong><span>/ 100</span></div><p class="score-caption">Observed anomaly score · not medical risk</p><div class="confidence"><span>Evidence confidence</span><strong>${Math.round(s.confidence*100)}%</strong></div><div class="meter"><i style="width:${s.confidence*100}%"></i></div><p class="assessment-copy">${copy}</p><div class="evidence">${Object.entries(s.features).map(([k,f])=>`<div class="evidence-row" title="${escape(f.reason)}"><span>${meta[k].name}</span><strong>${s.valid.includes(k)?'+'+f.contribution.toFixed(1):'Excluded'}</strong></div>`).join('')}<div class="evidence-row"><span>Sustained review evidence</span><strong>${Math.min(8,s.persistence).toFixed(0)} / 8 s</strong></div><div class="evidence-row"><span>Baseline model</span><strong>${s.baseline?'Calibrated':s.baselineProgress+' / 20'}</strong></div></div>`;
  $('assessment').insertAdjacentHTML('beforeend',`<div class="review-status"><strong>Observation: ${s.observationState}</strong><br>Review: ${s.reviewState}${s.episode?.timedOut?' · OVERDUE':''}</div><details id="explanation" ${explanationOpen?'open':''}><summary>Why this assessment?</summary><p class="assessment-copy">Evidence sufficiency (not probability): min(${s.confidenceExplanation.meanQuality.toFixed(3)}, ${s.confidenceExplanation.contextCap}) × ${s.confidenceExplanation.calibrationFactor} = ${s.confidence.toFixed(3)}.</p><p class="assessment-copy">${s.confidenceExplanation.reasons.map(escape).join('<br>')||'All four channels accepted; calibrated baseline.'}</p>${Object.entries(s.features).map(([k,f])=>`<p class="assessment-copy"><strong>${meta[k].name}</strong>: ${escape(f.reason)}${f.value!==null?`<br>Raw ${f.raw.toFixed(2)} → median ${f.value.toFixed(2)}; z ${f.z.toFixed(2)}.<br>max(rule ${f.rule.toFixed(2)}, novelty ${f.novelty.toFixed(2)}) × context ${f.context} × weight ${f.weight} = ${f.contribution.toFixed(2)}`:''}</p>`).join('')}<p class="assessment-copy">Review gates: ${Object.entries(s.gates).map(([k,v])=>`${k} ${v?'✓':'✗'}`).join(' · ')}.<br>Score range ${s.scoreRange.join('–')} bounds missing channel contributions only; it is not a statistical confidence interval.</p></details>`);
  renderReview();
  $('scenario-list').innerHTML=SCENARIOS.map(c=>`<button class="scenario ${scenario===c.id?'selected':''}" data-scenario="${c.id}" aria-pressed="${scenario===c.id}"><span>${c.label}</span><h3>${c.name}</h3><p>${c.description}</p><small>${scenario===c.id?'● Selected scenario':'Explore scenario →'}</small></button>`).join('');
  $('event-count').textContent=`${monitor.events.length} EVENTS · SESSION ONLY`;
  $('events').innerHTML=[...monitor.events].reverse().slice(0,40).map(e=>`<article class="event ${e.type}"><time>${time(e.t)}</time><span class="event-dot"></span><div><strong>${escape(e.title)}</strong><p>${escape(e.detail)}</p>${e.evidence?`<details><summary>View decision evidence</summary><p>${Object.entries(e.evidence).map(([k,f])=>`${meta[k].name}: ${f.value?.toFixed(1)??'excluded'}, contribution ${f.contribution.toFixed(1)}, directional z ${f.z?.toFixed(2)??'n/a'}, slope ${f.trend?.toFixed(1)??'n/a'}/min. ${escape(f.reason)}.`).join('<br>')}<br>Score ${e.score}; evidence confidence ${Math.round(e.confidence*100)}%; policy ${e.policy}.</p></details>`:''}</div><span class="event-id">${e.id}</span></article>`).join('');
}
function renderReview(){const e=monitor.latest.episode;if(e?.status==='pending'){if(reviewId===e.id)return;reviewId=e.id;$('review-panel').innerHTML=`<div class="review-box"><h3>Human confirmation</h3><p>Your decision is recorded locally in this session.</p><label class="sr-only" for="review-note">Review note (required)</label><textarea id="review-note" maxlength="500" placeholder="Describe what you observed…" required></textarea><p class="form-error" id="review-error" role="alert"></p><div class="review-actions"><button class="primary" data-review="confirm">Confirm concern</button><button class="secondary" data-review="dismiss">Dismiss</button></div></div>`;}else{reviewId=null;$('review-panel').innerHTML=e?`<div class="review-status">${e.status==='confirmed'?'✓ Concern confirmed.':'Review dismissed.'} Re-arming requires 10 seconds of reliable recovery.</div>`:'';}}
function review(action){try{monitor.review(monitor.latest.episode?.id,action,$('review-note').value,monitor.latest.t);reviewId=null;render();}catch(e){$('review-error').textContent=e.message;}}
$('play').addEventListener('click',()=>{if(running){stop();renderControls();}else start();});$('step').addEventListener('click',()=>advance());$('reset').addEventListener('click',()=>reset(scenario));$('speed').addEventListener('change',()=>{if(running)start();});
$('scenario-list').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(b)reset(b.dataset.scenario);});$('review-panel').addEventListener('click',e=>{const b=e.target.closest('[data-review]');if(b)review(b.dataset.review);});
$('policy-open').addEventListener('click',()=>$('policy-dialog').showModal());$('policy-close').addEventListener('click',()=>$('policy-dialog').close());
$('policy-content').innerHTML=`<table><tbody><tr><th>Signal quality</th><td>Accept quality ≥ 0.65, finite values in input bounds, and samples ≤ 3 seconds old. Detect 20 seconds of frozen numeric measurements.</td></tr><tr><th>Temporal model</th><td>5-second median. Learn median + MAD from 20 consecutive reliable resting samples, then freeze. Scale floors: HR 4, SpO₂ 0.8, RR 1.5.</td></tr><tr><th>Fusion</th><td>SpO₂ 45%, respiratory rate 30%, heart rate 25%. Missing channels contribute zero; their possible weight is shown as uncertainty.</td></tr><tr><th>Demo envelopes</th><td>HR: (value − 100) / 50. SpO₂: (96 − value) / 8. RR: (value − 22) / 12. Clamp each to 0–1.</td></tr><tr><th>Learned novelty</th><td>Directional z-score from baseline; 0.6 × clamp((z − 3) / 5). Take maximum of novelty and envelope severity. Activity ≥ 0.35 multiplies HR/RR severity by 0.15.</td></tr><tr><th>Confidence</th><td>Mean accepted quality across all four inputs. Halved before calibration; capped at 0.5 when activity is unreliable. Not a probability.</td></tr><tr><th>Review gate</th><td>Score ≥ 55, confidence ≥ 70%, ≥ 2 channels with severity ≥ 0.25, sustained for 8 seconds. Watch begins at 25.</td></tr><tr><th>Human authority</th><td>Confirmation alone enables demo high priority. Dismissal requires a note. After 30 seconds without response, review is overdue and remains unresolved.</td></tr><tr><th>Re-arm</th><td>Resolved review + score &lt; 20 + all channels reliable for 10 seconds. One review per episode.</td></tr></tbody></table><h3>Scope & limitations</h3><p>Only synthetic streams. No trained clinical model, medical diagnosis, actual device integration, background surveillance, external alerts, or durable audit store. The statistical baseline detector is fitted online; rules govern every escalation.</p>`;
// Keep the visible policy aligned with the corroboration veto and timer semantics.
for(const row of $('policy-content').querySelectorAll('tr')){
  const title=row.querySelector('th').textContent;
  if(title==='Learned novelty')row.querySelector('td').textContent='Directional baseline z-score; 0.6 × clamp((z − 3) / 5). Take the maximum of novelty and envelope severity. Activity ≥ 0.35 discounts HR/RR by 0.15, unless reliable oxygen severity ≥ 0.25 vetoes that discount.';
  if(title==='Re-arm')row.querySelector('td').textContent='After a decision, require score < 20 and all channels reliable for 10 seconds of consecutive new samples. Clock ticks cannot advance recovery.';
  if(title==='Confidence')row.querySelector('td').textContent='Evidence sufficiency = min(mean accepted quality, activity cap) × calibration factor. Cap is 0.5 without activity, otherwise 1; calibration factor is 0.5 before calibration, otherwise 1. Not a probability.';
}
$('export').addEventListener('click',async()=>{
  const button=$('export'),snapshot={...monitor.report(),scenario};button.disabled=true;
  try {
    const sealed=await sealReport(snapshot);
    const blob=new Blob([JSON.stringify(sealed,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download=`vitalguard-${snapshot.scenario}-session.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
    button.textContent='Session exported ✓';button.title=`SHA-256: ${sealed.digest}. Retain separately to detect replacement.`;
  }catch(error){button.textContent='Export failed · retry';button.title=error.message;}
  finally{button.disabled=false;}
});
// Progressive enhancement: feature-detect the proposed page-scoped agent interface.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_vitalguard_session',description:'Read synthetic monitoring state and audit events. Does not perform human confirmation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected empty input');return monitor.report();}})).catch(()=>{});}catch{}}
reset(scenario);
